   111  void HashMgr::free_table() {
   112    // now pass through hash table freeing up everything
   113    // go through column by column of the table
   114    for (size_t i = 0; i < tableptr.size(); ++i) {
   115      struct hentry* pt = tableptr[i];
   116      struct hentry* nt = NULL;
   117      while (pt) {
   118        nt = pt->next;
   119        free_flag(pt->astr, pt->alen);
   120        free(pt);
   121        pt = nt;
   122      }
   123    }
   124    tableptr.clear();
   125  }
