   150  // lookup a root word in the hashtable
   151
   152  struct hentry* HashMgr::lookup(const char* word) const {
   153    struct hentry* dp = tableptr[hash(word)];
   154    if (!dp)
   155      return NULL;
   156    for (; dp != NULL; dp = dp->next) {
   157      if (strcmp(word, dp->word) == 0)
   158        return dp;
   159    }
   160    return NULL;
   161  }
